window.LESSONS.forEach(lesson => {
  lesson.vocab.push(...sprintVocabulary[lesson.id]);
  lesson.grammar.push(...extraGrammar[lesson.id]);
  lesson.lgsQuestions = lgs[lesson.id];
  lesson.lgsQuestions.push(...moreLgs[lesson.id]);
  lesson.extraReadings = extraReadings[lesson.id];
  lesson.vocabularyPractice = vocabularyPractice[lesson.id];
  lesson.speakingExercises = speakingExercises[lesson.id];
  const extension = termOneExtensions[lesson.id];
  if (extension) {
    lesson.outcomes = extension.outcomes;
    lesson.grammar.push(...extension.grammar);
    lesson.vocab.push(...extension.vocab);
    lesson.extraReadings.push(...extension.readings);
    lesson.speakingExercises.push(...extension.speaking);
    lesson.writing = extension.writing;
    lesson.lgsQuestions.push(...extension.lgs);
    (extraLgsScenarios[lesson.id] || []).forEach((context,index) => {
      [0,1].forEach(offset => { const question=lesson.lgsQuestions[20+index*2+offset]; if(question)question[4]=context; });
    });
  }
  lesson.examQuestions = lgsMiniDeneme[lesson.id];
});
